import fs from 'node:fs';import assert from 'node:assert/strict';import {createHash} from 'node:crypto';
const expected=JSON.parse(fs.readFileSync(new URL('./release-097-expected.json',import.meta.url))),origin='https://updates.dzimplei.com/desktop/',proof=[];
for(const [name,text]of Object.entries(expected.rawFeeds)){const r=await fetch(origin+name+'?verify='+Date.now(),{signal:AbortSignal.timeout(30000)});assert(r.ok,name);assert.equal(await r.text(),text,name+' must match the locally parsed and verified feed exactly');assert.equal(expected.feeds[name].version,'0.9.7');assert.equal(expected.feeds[name].sourceRevision,process.env.SOURCE_REF);proof.push({feed:name,version:'0.9.7',sourceRevision:process.env.SOURCE_REF});}
await Promise.all(Object.values(expected.assets).map(async a=>{const r=await fetch(origin+a.url,{signal:AbortSignal.timeout(840000)});assert(r.ok,a.url);const h=createHash('sha512'),h256=createHash('sha256');let size=0;for await(const b of r.body){h.update(b);h256.update(b);size+=b.length;}const sha512=h.digest('base64');assert.equal(sha512,a.sha512,a.url);assert.equal(size,a.size,a.url);proof.push({artifact:a.url,size,sha512,sha256:h256.digest('hex')});console.log('Verified downloaded checksum and byte count:',a.url,size);}));
fs.writeFileSync('release-097-proof.json',JSON.stringify({verificationHost:'GitHub hosted runner',checks:proof},null,2)+'\n');console.log('All four feeds and all five published archives verified.');
